import WaveSurfer from './assets/wavesurfer.esm.js';
const intro=document.querySelector('#intro'),video=document.querySelector('#intro-video'),start=document.querySelector('#start-intro'),collection=document.querySelector('#collection'),status=document.querySelector('#status');
let active=null,players=[],mounted=false,items=[],leaving=false,exitTimer;
const fmt=t=>`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;
function stopActive(except){if(active&&active!==except){active.pause();active.setTime(0)}active=except}
function showCollection(){if(leaving)return;leaving=true;video.pause();collection.hidden=false;collection.inert=false;document.body.classList.remove('intro-active');intro.classList.add('leaving');if(!mounted&&items.length)mount();exitTimer=setTimeout(()=>{intro.hidden=true;document.querySelector('#replay').focus({preventScroll:true})},180)}
async function playIntro(){start.hidden=true;video.hidden=false;try{await video.play()}catch{if(!leaving){video.hidden=true;start.hidden=false;start.focus()}}}
function replay(){clearTimeout(exitTimer);stopActive(null);leaving=false;intro.hidden=false;intro.classList.remove('leaving');collection.hidden=true;collection.inert=true;document.body.classList.add('intro-active');video.currentTime=0;playIntro()}
start.onclick=playIntro;document.querySelector('#replay').onclick=replay;video.onended=showCollection;video.onerror=()=>{start.hidden=true;document.querySelector('#intro-error').hidden=false;setTimeout(showCollection,1500)};start.focus();
function mount(){mounted=true;items.forEach((item,i)=>{const card=document.createElement('article');card.className='card';card.innerHTML=`<div class="meta">VOICE NOTE / ${String(i+1).padStart(2,'0')}</div><h3></h3><div class="transport"><button class="play" disabled>▶</button><div class="wave"></div></div><div class="timing"><span class="elapsed">0:00</span><button class="speed" disabled>1×</button><span class="duration">—</span></div><p class="error" hidden>Recording unavailable.</p>`;card.querySelector('h3').textContent=item.title;const column=document.querySelector(i<Math.ceil(items.length/2)?'#left':'#right');column.append(card);const photoBreaks={1:[12,'Photo souvenir au jardin'],3:[1,'Une peluche rose sur le canapé'],5:[8,'Souvenir de plage'],7:[3,'Photo de groupe devant un miroir'],11:[10,'Au bord de la mer'],13:[4,'Photo souvenir sur le lit'],15:[11,'Selfie de soirée'],17:[5,'Photo de soirée entre amis']};if(photoBreaks[i]){const [number,alt]=photoBreaks[i];const figure=document.createElement('figure');figure.className='photo-break photo-'+number;const image=document.createElement('img');image.src='./assets/photos/photo-'+number+([8,10].includes(number)?'-mo-sticker-v3.png':'.jpg');image.alt=alt;image.loading='lazy';image.decoding='async';figure.append(image);column.append(figure);}const play=card.querySelector('.play'),speed=card.querySelector('.speed');play.setAttribute('aria-label',`Play ${item.title}`);speed.setAttribute('aria-label',`Playback speed for ${item.title}: 1×`);
const ws=WaveSurfer.create({container:card.querySelector('.wave'),url:item.audio,height:58,waveColor:'#55534e',progressColor:'#ff9900',cursorColor:'#ffe0af',barWidth:2,barGap:2,barRadius:2,normalize:true});players.push(ws);
const playError=()=>{card.querySelector('.error').hidden=false;status.textContent=`Could not play ${item.title}.`};
play.onclick=()=>{stopActive(ws);ws.playPause().catch(playError)};ws.on('interaction',()=>{stopActive(ws);ws.play().catch(playError)});ws.on('play',()=>{stopActive(ws);card.classList.add('playing');play.textContent='Ⅱ';play.setAttribute('aria-label',`Pause ${item.title}`);status.textContent=`Playing: ${item.title}`});ws.on('pause',()=>{card.classList.remove('playing');play.textContent='▶';play.setAttribute('aria-label',`Play ${item.title}`)});ws.on('finish',()=>{ws.setTime(0);status.textContent=`Finished: ${item.title}`});ws.on('timeupdate',t=>card.querySelector('.elapsed').textContent=fmt(t));ws.on('ready',()=>{play.disabled=false;speed.disabled=false;card.querySelector('.duration').textContent=fmt(ws.getDuration())});ws.on('error',playError);speed.onclick=()=>{const rates=[1,1.25,1.5,.75];const rate=rates[(rates.indexOf(ws.getPlaybackRate())+1)%rates.length];ws.setPlaybackRate(rate,true);speed.textContent=rate+'×';speed.setAttribute('aria-label',`Playback speed for ${item.title}: ${rate}×`)};
})}
fetch('./samples.json').then(r=>{if(!r.ok)throw Error('samples');return r.json()}).then(data=>{items=data;if(!mounted)mount()}).catch(()=>document.querySelector('#load-error').hidden=false);
